// Runs the hand-written 68020/68030/68040 cases from cpu020_cases.h
// (generated by tools/gen_cpu020_tests.py).
#include <cstdio>
#include <cstring>
#include <vector>
#include <cmath>
#include "../src/core/m68k.h"
#include "../src/core/fpu.h"

using namespace macemu;

struct Init { int reg; u32 value; };
enum { X_END, X_REG, X_CCR, X_VECTOR, X_MEM, X_FPSR };
struct Expect { int kind; int a; u32 addr; u32 value; u32 mask; };
enum { FINF = 1000000, FNAN = 2000000 };
struct FExpect { int reg; long double value; long double tol; };
struct Case { const char *name; int model; int fpu; u32 sr; const unsigned char *code; u32 len; const Init *init; const Expect *expect; const FExpect *fexpect; };

#include "cpu020_cases.h"

enum { kMemSize = 1 << 20, kHandlers = 0x800 };

// Flat 1 MB of RAM; 0x9xxxxxxx raises bus errors.
struct TestBus : Bus {
    std::vector<u8> mem = std::vector<u8>(kMemSize);
    bool fault(u32 a, bool w) { if ((a >> 28) == 9) { signalBusError(a, w); return true; } return false; }
    u8 read8(u32 a) override { return fault(a, false) ? 0xFF : mem[a & (kMemSize - 1)]; }
    u16 read16(u32 a) override { return (u16)((read8(a) << 8) | read8(a + 1)); }
    void write8(u32 a, u8 v) override { if (!fault(a, true)) mem[a & (kMemSize - 1)] = v; }
    void write16(u32 a, u16 v) override { write8(a, (u8)(v >> 8)); write8(a + 1, (u8)v); }
};

int main(int argc, char **argv)
{
    bool verbose = argc > 1;
    int failed = 0, total = 0;
    for (const Case &c : kCases) {
        total++;
        TestBus bus;
        for (u32 v = 0; v < 256; v++) putBe32(&bus.mem[v * 4], kHandlers + v * 4);
        memcpy(&bus.mem[0x1000], c.code, c.len);
        M68K cpu(&bus);
        cpu.setModel(c.model);
        Fpu fpu(c.fpu);
        if (c.fpu) cpu.attachFpu(&fpu);
        cpu.setSR(0x2700);
        cpu.a[7] = 0x8000;
        cpu.setUSP(0x7000);
        for (const Init *i = c.init; i->reg >= 0; i++) {
            if (i->reg < 8) cpu.d[i->reg] = i->value; else cpu.a[i->reg - 8] = i->value;
        }
        if (!(c.sr & 0x2000)) cpu.setUSP(cpu.a[7]);     // user-mode cases start on the USP
        cpu.setSR((u16)c.sr);
        if (!(c.sr & 0x2000)) cpu.a[7] = 0x7000;
        cpu.pc = 0x1000;

        int vector = -1;
        for (int n = 0; n < 200; n++) {
            cpu.step();
            if (cpu.pc >= kHandlers && cpu.pc < kHandlers + 0x400) { vector = (int)(cpu.pc - kHandlers) / 4; break; }
        }

        char why[512] = "";
        auto bad = [&](const char *fmt, u32 a, u32 got, u32 want) {
            char b[96];
            snprintf(b, sizeof b, fmt, a, got, want);
            strncat(why, b, sizeof why - strlen(why) - 1);
        };
        for (const Expect *e = c.expect; e->kind != X_END; e++) {
            switch (e->kind) {
            case X_REG: {
                u32 got = e->a < 8 ? cpu.d[e->a] : cpu.a[e->a - 8];
                if (got != e->value) {
                    char fmt[40];
                    snprintf(fmt, sizeof fmt, " %c%d=%%.0X%%08X(want %%08X)", e->a < 8 ? 'd' : 'a', e->a & 7);
                    bad(fmt, 0, got, e->value);
                }
                break;
            }
            case X_CCR: {
                u32 got = cpu.getSR() & e->mask;
                if (got != e->value) bad(" ccr&%02X=%02X(want %02X)", e->mask, got, e->value);
                break;
            }
            case X_VECTOR:
                if (vector != (int)e->value) bad(" vector%u=%d(want %u)", 0, (u32)vector, e->value);
                break;
            case X_FPSR: {
                u32 got = fpu.fpsr & e->mask;
                if (got != e->value) bad(" fpsr&%08X=%08X(want %08X)", e->mask, got, e->value);
                break;
            }
            case X_MEM: {
                u32 got = 0;
                for (int i = 0; i < e->a; i++) got = (got << 8) | bus.mem[(e->addr + i) & (kMemSize - 1)];
                if (got != e->value) bad(" [%X]=%X(want %X)", e->addr, got, e->value);
                break;
            }
            }
        }
        for (const FExpect *f = c.fexpect; f->reg >= 0; f++) {
            long double got = fpu.fp[f->reg];
            bool ok;
            if (f->value == FINF) ok = std::isinf(got);
            else if (f->value == FNAN) ok = std::isnan(got);
            else ok = fabsl(got - f->value) <= f->tol * fabsl(f->value);
            if (!ok) {
                char b[128];
                snprintf(b, sizeof b, " fp%d=%.20Lg(want %.20Lg)", f->reg, got, f->value);
                strncat(why, b, sizeof why - strlen(why) - 1);
            }
        }
        if (why[0]) { failed++; printf("FAIL %-45s%s\n", c.name, why); }
        else if (verbose) printf("ok   %s\n", c.name);
    }
    printf("%d cases, %d failed\n", total, failed);
    return failed ? 1 : 0;
}
